#include <iostream>
using namespace std;

struct Node { int data; Node* next; Node(int v):data(v),next(nullptr){} };

void insertAtHead(Node*& head, int val) {
    Node* n = new Node(val);
    n->next = head;
    head = n;
}

void insertAtEnd(Node*& head, int val) {
    Node* n = new Node(val);
    if (!head) { head = n; return; }
    Node* curr = head;
    while (curr->next) curr = curr->next;
    curr->next = n;
}

void deleteNode(Node*& head, int val) {
    if (!head) return;
    if (head->data == val) { Node* tmp = head; head = head->next; delete tmp; return; }
    Node* curr = head;
    while (curr->next && curr->next->data != val) curr = curr->next;
    if (curr->next) { Node* tmp = curr->next; curr->next = tmp->next; delete tmp; }
}

void print(Node* head) {
    for (Node* c = head; c; c = c->next) cout << c->data << " ";
    cout << endl;
}

int main() {
    Node* head = nullptr;
    insertAtEnd(head, 1); insertAtEnd(head, 2); insertAtEnd(head, 3);
    insertAtHead(head, 0);
    print(head);
    deleteNode(head, 2);
    print(head);
    return 0;
}

