#include <iostream>
using namespace std;
struct Node { int data; Node* next; Node(int v):data(v),next(nullptr){} };
// Reverse
Node* reverse(Node* head) {
    Node *prev=nullptr, *curr=head, *nxt=nullptr;
    while (curr) { nxt=curr->next; curr->next=prev; prev=curr; curr=nxt; }
    return prev;
}
// Detect cycle
bool hasCycle(Node* head) {
    Node *slow=head, *fast=head;
    while (fast && fast->next) {
        slow=slow->next; fast=fast->next->next;
        if (slow==fast) return true;
    }
    return false;
}
// Find middle
Node* findMiddle(Node* head) {
    Node *slow=head, *fast=head;
    while (fast && fast->next) { slow=slow->next; fast=fast->next->next; }
    return slow;
}
int main() {
    Node* h=new Node(1); h->next=new Node(2); h->next->next=new Node(3); h->next->next->next=new Node(4); h->next->next->next->next=new Node(5);
    cout << "Middle: " << findMiddle(h)->data << endl;
    h=reverse(h);
    for(Node* c=h;c;c=c->next) cout<<c->data<<" "; cout<<endl;
    return 0;
}

